parameters.query:
SELECT ba.id::text AS account_id,ba.business_id,b.business_name,ba.operations_spreadsheet_id AS sheet_document_id,ba.human_support_sheet_name
FROM business_accounts ba JOIN businesses b ON b.business_id=ba.business_id
WHERE ba.active=TRUE AND b.active=TRUE AND COALESCE(ba.operations_spreadsheet_id,'')<>'';
